CREATE TABLE campaign_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,meta_asset_id uuid REFERENCES meta_user_assets(id) ON DELETE SET NULL,name text NOT NULL,objective text NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PAUSED','ACTIVE','ERROR')),daily_budget numeric(14,2),currency text,starts_at timestamptz,ends_at timestamptz,configuration jsonb NOT NULL DEFAULT '{}'::jsonb,meta_campaign_id text UNIQUE,idempotency_key uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX campaign_drafts_user_idx ON campaign_drafts(user_id,created_at DESC);
